// Checks texts generated by Pandore (emails, labels) against the vocabulary
// rules of the Junior-Entreprise, which is not an employer (see CLAUDE.md).

// Patterns are written without accents: the text is compared without accents
// and in lowercase, so "Rémunération", "REMUNERATION" and "rémunérations" all match.
const RULES = [
  {
    pattern: /\bremunerations?\b/g,
    term: 'rémunération',
    suggestion: 'rétribution',
  },
  { pattern: /\bsalaires?\b/g, term: 'salaire', suggestion: 'rétribution' },
  { pattern: /\bsalariee?s?\b/g, term: 'salarié', suggestion: 'intervenant' },
  { pattern: /\bemployee?s?\b/g, term: 'employé', suggestion: 'intervenant' },
  {
    pattern: /\brecrut(?:ement|ements|er|e|es|ons|ez|ent)\b/g,
    term: 'recrutement',
    suggestion: 'sélection',
  },
  {
    pattern: /\bconsultante?s?\b/g,
    term: 'consultant',
    suggestion: 'intervenant',
  },
  {
    pattern: /\bcontrats? de travail\b/g,
    term: 'contrat de travail',
    suggestion: 'récapitulatif de mission (RDM)',
  },
  {
    pattern: /\bcabinets? de conseil\b/g,
    term: 'cabinet de conseil',
    suggestion: 'association pédagogique de conseil',
  },
  {
    pattern: /\b\d+(?:[.,]\d+)?\s*fois moins chers?\b/g,
    term: '« X fois moins cher »',
    suggestion: 'tarifs attractifs',
  },
  {
    pattern: /\bmoins chers? que\b/g,
    term: 'comparaison de prix',
    suggestion: 'tarifs attractifs',
  },
  {
    pattern: /\bconcurrents?\b/g,
    term: 'comparaison avec un concurrent',
    suggestion: 'présenter AJC sans se comparer',
  },
];

// Lowercase and remove accents, character by character, so that positions in
// the simplified text match positions in the original text.
function simplify(text) {
  let result = '';
  for (let i = 0; i < text.length; i += 1) {
    const plain = text[i].normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
    result +=
      plain.length === 1 ? plain : (text[i].toLowerCase()[0] ?? text[i]);
  }
  return result;
}

// Returns the problems found, in the order they appear in the text:
// [{ term, suggestion, start, end, excerpt }]
export function checkVocabulary(text) {
  const simplified = simplify(String(text ?? ''));
  const issues = [];
  for (const rule of RULES) {
    for (const match of simplified.matchAll(rule.pattern)) {
      issues.push({
        term: rule.term,
        suggestion: rule.suggestion,
        start: match.index,
        end: match.index + match[0].length,
        excerpt: text.slice(match.index, match.index + match[0].length),
      });
    }
  }
  return issues.sort((a, b) => a.start - b.start);
}
